% Step 1: 用轮盘赌选一个指标（SDE/I_epsilon+/Minkowski） [Fitness, indicator_flag, Lp] = IndicatorSelector(Population, indicator, Lp);
% Step 2: 用 SVR（支持向量回归）训练一个快速预测该指标的模型 IndicatorModel = fitrsvm(Population.decs, Fitness, ... 'KernelFunction', 'rbf', 'KernelScale', 'auto', 'Standardize', true);
% Step 3: 如果指标模型构建成功 + 模型精度好 + 退化度高 % → Smodel.mode = 'indicator'（第 199 行）

function Next = select_indicator(Smodel, Candidates, n_min, n_max)
    % 第一阶段：关系得分粗筛（保留前 30%，至少 20 个）
    [~, scores_rel] = model_select(Smodel, Candidates);
    n_keep = max(20, ceil(size(Candidates, 1) * 0.30));
    [~, idx_rel] = sort(scores_rel, 'descend');
    coarse_idx = idx_rel(1:n_keep);

    % 第二阶段：用 SVR 指标模型重排序
    pred = predict(Smodel.IndicatorModel, Candidates(coarse_idx, :));
    scores_ind = pred;  % 用 SVR 预测的指标值替代关系得分

    % 分位数筛选 + 排序选出 top 候选
    threshold = quantile(scores_ind, 0.70);
    ...
end

